export function getPatternMappings(slug: string): PatternQuestionMapping[] {
  return PATTERN_MAPPINGS_BY_SLUG[slug] || [];
}

export const TOTAL_PATTERN_MAPPINGS_COUNT = ALL_PATTERN_MAPPINGS.length;

export const UNIQUE_PATTERN_QUESTION_IDS: number[] = Array.from(
  new Set(ALL_PATTERN_MAPPINGS.map(m => m.questionId))
);

export const UNIQUE_PATTERN_QUESTIONS_COUNT = UNIQUE_PATTERN_QUESTION_IDS.length;

export function getCrossPatternQuestions(): {
  questionId: number;
  occurrences: number;
  patterns: string[];
}[] {
  const map = new Map<number, string[]>();
  for (const [slug, mappings] of Object.entries(PATTERN_MAPPINGS_BY_SLUG)) {
    for (const mapping of mappings) {
      const list = map.get(mapping.questionId) || [];
      list.push(slug);
      map.set(mapping.questionId, list);
    }
  }

  const crossQuestions: {
    questionId: number;
    occurrences: number;
    patterns: string[];
  }[] = [];

  for (const [questionId, patterns] of map.entries()) {
    if (patterns.length > 1) {
      crossQuestions.push({
        questionId,
        occurrences: patterns.length,
        patterns,
      });
    }
  }

  return crossQuestions;
}
